1	//! Helpers for the `PUT /:pkg` publish endpoint.
2	//!
3	//! npm sends the entire packument plus base64-encoded tarballs in a
4	//! single JSON body. This module pulls the attachment metadata out of
5	//! the body, merges the incoming manifest into whatever packument is
6	//! already on disk, and provides the streaming decode/verify/write
7	//! routine the handler uses to persist each tarball. The actual I/O
8	//! lives here behind a sync interface so the publish handler can run
9	//! it inside [`tokio::task::spawn_blocking`] without blocking the
10	//! async runtime, and so these helpers stay easy to unit-test.
11	
12	use crate::{
13	    error::RegistryError,
14	    streaming::{integrity_checker, parse_integrity},
15	};
16	use base64::{Engine, engine::general_purpose::STANDARD as BASE64, read::DecoderReader};
17	use serde_json::{Map, Value};
18	use ssri::{Algorithm, IntegrityOpts};
19	use std::{
20	    collections::BTreeMap,
21	    fmt::Write as FmtWrite,
22	    fs::File,
23	    io::{Cursor, Read, Write},
24	    path::Path,
25	};
26	
27	/// Per-tarball metadata pulled out of an `_attachments` entry. We
28	/// hold the base64 payload as an owned `String` rather than decoding
29	/// it eagerly — the streaming write path consumes it directly and
30	/// the decoded bytes never have to live in memory.
31	#[derive(Debug)]
32	pub struct PendingAttachment {
33	    pub filename: String,
34	    /// Base64-encoded tarball, taken verbatim from the publish body.
35	    pub data: String,
36	    /// `_attachments.<filename>.length` — the declared byte count of
37	    /// the *decoded* tarball, used to catch truncated uploads.
38	    pub declared_length: Option<u64>,
39	}
40	
41	/// Pull all `_attachments` out of a publish body. Returns one
42	/// [`PendingAttachment`] per entry and removes the `_attachments`
43	/// field from `body` so the saved packument doesn't duplicate the
44	/// on-disk tarball. Base64 decoding is deferred to the streaming
45	/// write path; this function just validates shape.
46	pub fn extract_attachments(body: &mut Value) -> Result<Vec<PendingAttachment>, RegistryError> {
47	    let Some(obj) = body.as_object_mut() else {
48	        return Ok(Vec::new());
49	    };
50	    let Some(attachments_value) = obj.remove("_attachments") else {
51	        return Ok(Vec::new());
52	    };
53	    let Value::Object(attachments) = attachments_value else {
54	        return Err(RegistryError::BadRequest {
55	            reason: "_attachments must be an object".to_string(),
56	        });
57	    };
58	    let mut out = Vec::with_capacity(attachments.len());
59	    for (filename, value) in attachments {
60	        let Value::Object(mut value_obj) = value else {
61	            return Err(RegistryError::InvalidAttachment {
62	                filename,
63	                reason: "expected object".to_string(),
64	            });
65	        };
66	        let Some(Value::String(data)) = value_obj.remove("data") else {
67	            return Err(RegistryError::InvalidAttachment {
68	                filename,
69	                reason: "missing string field `data`".to_string(),
70	            });
71	        };
72	        let declared_length = value_obj.get("length").and_then(Value::as_u64);
73	        out.push(PendingAttachment { filename, data, declared_length });
74	    }
75	    Ok(out)
76	}
77	
78	/// Stream-decode a base64 attachment, hash it as it flows by, and
79	/// write the bytes to `dest`. Fails fast (and leaves no on-disk
80	/// artifact other than the caller-supplied tmp file) if the decoded
81	/// tarball doesn't match the declared `dist.integrity` SRI, the
82	/// optional legacy `dist.shasum`, or the declared `length`.
83	///
84	/// Synchronous on purpose: the publish handler runs this inside
85	/// [`tokio::task::spawn_blocking`] so the base64-decode and hashing
86	/// stages can use plain `std::io` and operate on chunks small enough
87	/// (`CHUNK_BYTES`) that the full decoded payload never lives in
88	/// memory at once — only the original base64 string (held by the
89	/// JSON value) and a 64 KiB working buffer.
90	///
91	/// `dist.integrity` is required. npm always emits it; a body that
92	/// arrives without it is either tampered with or produced by a
93	/// buggy client, and accepting it would store a tarball whose hash
94	/// the registry never verified. All EINTEGRITY-class failures
95	/// surface with an `EINTEGRITY:` prefix so pnpm / npm clients can
96	/// recognize them.
97	pub fn stream_decode_verify_and_write(
98	    filename: &str,
99	    base64_data: &str,
100	    declared_length: Option<u64>,
101	    dist: Option<&Value>,
102	    dest: &Path,
103	) -> Result<u64, RegistryError> {
104	    let invalid = |reason: String| RegistryError::InvalidAttachment {
105	        filename: filename.to_string(),
106	        reason,
107	    };
108	    let dist = dist.ok_or_else(|| {
109	        invalid(
110	            "EINTEGRITY: packument has no matching versions[v].dist entry for this attachment"
111	                .to_string(),
112	        )
113	    })?;
114	    let declared_integrity = dist
115	        .get("integrity")
116	        .and_then(Value::as_str)
117	        .ok_or_else(|| invalid("EINTEGRITY: dist.integrity is required".to_string()))?;
118	    let integrity = parse_integrity(declared_integrity)
119	        .map_err(|err| invalid(format!("EINTEGRITY: malformed dist.integrity: {err}")))?;
120	    let declared_shasum = dist.get("shasum").and_then(Value::as_str);
121	
122	    let mut checker = integrity_checker(&integrity)
123	        .map_err(|err| invalid(format!("EINTEGRITY: malformed dist.integrity: {err}")))?;
124	    let mut shasum_hasher =
125	        declared_shasum.is_some().then(|| IntegrityOpts::new().algorithm(Algorithm::Sha1));
126	
127	    let mut decoder = DecoderReader::new(Cursor::new(base64_data.as_bytes()), &BASE64);
128	    let mut file = File::create(dest).map_err(RegistryError::Io)?;
129	    const CHUNK_BYTES: usize = 64 * 1024;
130	    let mut buf = vec![0u8; CHUNK_BYTES];
131	    let mut total: u64 = 0;
132	    loop {
133	        let bytes_read = match decoder.read(&mut buf) {
134	            Ok(0) => break,
135	            Ok(bytes_read) => bytes_read,
136	            Err(err) => {
137	                let _ = std::fs::remove_file(dest);
138	                return Err(invalid(format!("EINTEGRITY: base64 decode failed: {err}")));
139	            }
140	        };
141	        let chunk = &buf[..bytes_read];
142	        if let Err(err) = file.write_all(chunk) {
143	            let _ = std::fs::remove_file(dest);
144	            return Err(RegistryError::Io(err));
145	        }
146	        checker.input(chunk);
147	        if let Some(hasher) = shasum_hasher.as_mut() {
148	            hasher.input(chunk);
149	        }
150	        total += bytes_read as u64;
151	    }
152	
153	    if let Some(expected) = declared_length
154	        && expected != total
155	    {
156	        let _ = std::fs::remove_file(dest);
157	        return Err(invalid(format!(
158	            "EINTEGRITY: length mismatch: header says {expected}, decoded {total}",
159	        )));
160	    }
161	
162	    if let Err(err) = checker.result() {
163	        let _ = std::fs::remove_file(dest);
164	        return Err(invalid(format!("EINTEGRITY: integrity mismatch: {err}")));
165	    }
166	    if let Some(declared) = declared_shasum {
167	        let hasher = shasum_hasher.expect("shasum_hasher initialized when declared_shasum present");
168	        let computed = sha1_hex_from_integrity_opts(hasher);
169	        if !computed.eq_ignore_ascii_case(declared) {
170	            let _ = std::fs::remove_file(dest);
171	            return Err(invalid(format!(
172	                "EINTEGRITY: shasum mismatch: declared {declared:?}, computed {computed:?}",
173	            )));
174	        }
175	    }
176	
177	    if let Err(err) = file.sync_all() {
178	        let _ = std::fs::remove_file(dest);
179	        return Err(RegistryError::Io(err));
180	    }
181	    O
