11	fn sri_sha512(bytes: &[u8]) -> String {
12	    let mut opts = IntegrityOpts::new().algorithm(Algorithm::Sha512);
13	    opts.input(bytes);
14	    opts.result().to_string()
15	}
16	
17	fn sha1_hex(bytes: &[u8]) -> String {
18	    let mut opts = IntegrityOpts::new().algorithm(Algorithm::Sha1);
19	    opts.input(bytes);
20	    sha1_hex_from_integrity_opts(opts)
21	}
