245	/// Discard an unsealed transaction: nothing of it ever became visible,
246	/// so all there is to do is delete the staged tmp files it points at
247	/// and the journal entry itself. Errors are swallowed — this is
248	/// cleanup, and a leftover tmp file is harmless beyond a little disk.
249	async fn roll_back(dir: &Path) {
250	    if let Ok(bytes) = fs::read(dir.join(MANIFEST_FILE)).await
251	        && let Ok(manifest) = serde_json::from_slice::<Manifest>(&bytes)
252	    {
253	        for package in &manifest.packages {
254	            for tarball in &package.tarballs {
255	                let _ = fs::remove_file(&tarball.tmp_path).await;
256	            }
257	        }
258	    }
259	    let _ = fs::remove_dir_all(dir).await;
260	}
