21	pub fn build_storage() -> TempDir {
22	    let dir = TempDir::new().expect("create temp storage dir");
23	    write_package(dir.path(), "@foo/no-deps", "no-deps-1.0.0.tgz", no_deps_packument());
24	    write_package(
