37	fn write_package(storage: &Path, name: &str, tarball: &str, packument: Value) {
38	    let package_dir = storage.join(name);
39	    std::fs::create_dir_all(&package_dir).expect("create package dir");
40	    std::fs::write(package_dir.join("package.json"), serde_json::to_vec(&packument).unwrap())
