811	    let full: Value = serde_json::from_slice(&body_bytes(full.into_body()).await).unwrap();
812	    assert_eq!(
813	        full["versions"]["1.0.0"]["dist"]["tarball"],
814	        "http://example.test/foo/-/foo-2.0.0.tgz",
815	    );
816	    assert_eq!(
817	        full["versions"]["2.0.0"]["dist"]["tarball"],
