299	/// present in `hosted` is immutable except for its `deprecated` flag
300	/// (see [`merge_hosted_version`]); every other incoming entry
301	/// overwrites verbatim. When `hosted` is `None`, all incoming entries
302	/// win — the upstream-only case, where nothing is locally immutable.
303	fn merge_versions(existing: Option<&Value>, incoming: &Value, hosted: Option<&Value>) -> Value {
304	    let mut merged = match existing {
305	        Some(Value::Object(obj)) => obj.clone(),
306	        _ => Map::new(),
307	    };
308	    let hosted_versions = hosted.and_then(Value::as_object);
309	    if let Some(incoming_obj) = incoming.as_object() {
310	        for (version, incoming_entry) in incoming_obj {
311	            let entry = match hosted_versions.and_then(|hosted| hosted.get(version)) {
312	                Some(hosted_entry) => merge_hosted_version(hosted_entry, incoming_entry),
313	                None => incoming_entry.clone(),
314	            };
315	            merged.insert(version.clone(), entry);
316	        }
317	    }
