321	/// Merge an incoming entry for an already-hosted version. The hosted
322	/// version's metadata is immutable — `dist.integrity`, dependencies,
323	/// and every other field are preserved verbatim — with one exception:
324	/// the `deprecated` flag tracks the incoming entry. When the incoming
325	/// entry carries `deprecated`, that value replaces the hosted one;
326	/// when it omits `deprecated`, the key is removed. A non-object
327	/// incoming entry (e.g. `null`) is ignored entirely, leaving the
328	/// hosted version untouched.
329	fn merge_hosted_version(hosted_entry: &Value, incoming_entry: &Value) -> Value {
330	    let Value::Object(hosted_obj) = hosted_entry else {
331	        return hosted_entry.clone();
332	    };
333	    let mut merged = hosted_obj.clone();
334	    if let Some(incoming_obj) = incoming_entry.as_object() {
335	        match incoming_obj.get("deprecated") {
336	            Some(deprecated) => {
337	                merged.insert("deprecated".to_string(), deprecated.clone());
338	            }
339	            None => {
340	                merged.remove("deprecated");
341	            }
342	        }
343	    }
344	    Value::Object(merged)
